#!/usr/bin/env bash
# batch_p06a_operational_readiness.sh
#
# P0.6 Batch A (G10, disasters 19/21 baseline) - operational readiness:
#   - GET /readyz  (503 if redis-durable unreachable, spool stale > SPOOL_STALE_S,
#     MAX_SESSIONS reached, or shutdown already started)
#   - GET /metrics (Bearer METRICS_TOKEN-protected; prom-client Registry;
#     default process/runtime metrics + session_state/session_reconnects_total/
#     lease_lost_total wired to real P0.5 transition points)
#   - main() refuses to start at all with an empty/missing METRICS_TOKEN (H5)
#   - Extended graceful shutdown: stop new HTTP requests -> drain in-flight
#     media downloads (bounded) -> close sockets without logout() + flush spool
#     + release leases -> exit within SHUTDOWN_TIMEOUT_MS (<= 25s), with a
#     hard fallback force-exit if any step hangs
#   - H12 structured logging: logEvent() helper + phone-number redaction
#     (last 3 digits visible) applied globally via a pino formatters.log hook
#
# Deliberately NOT in this batch (documented in docs/P0_DEVIATIONS.md D-22,
# not forgotten): the kill-switch (Batch B) and the ingest/outbound/forwarder/
# media/dlq/stream Prometheus metric families + ops/prometheus/*.yml + the
# docker-compose.yml/Dockerfile memory-limit change (Batch C).
#
# This script only WRITES files, installs the one new dependency
# (prom-client, already pinned in package.json - this regenerates
# package-lock.json for THIS machine rather than shipping a lockfile built
# elsewhere), and re-verifies (syntax + the full real-Redis test suite,
# including two new real-process P0.6 tests). It does NOT run `git add`/
# `git commit` - that is the next, separate, reviewed step.
#
# Run from the repository root: /home/sharwa/sharwa_ai
set -euo pipefail

REPO_ROOT="/home/sharwa/sharwa_ai"
if [ ! -d "$REPO_ROOT/gateway" ]; then
  echo "ERROR: $REPO_ROOT/gateway not found. Run this script from a machine where the repo lives at $REPO_ROOT, or edit REPO_ROOT at the top of this script." >&2
  exit 1
fi
cd "$REPO_ROOT"

echo "=== [0/6] Pre-flight: repo root = $REPO_ROOT ==="
git rev-parse --is-inside-work-tree >/dev/null 2>&1 && echo "  git repo: OK" || { echo "ERROR: not a git repository" >&2; exit 1; }

echo ""
echo "=== [1/6] Writing files (base64-embedded, decoded in place) ==="

write_file() {
  local path="$1"
  mkdir -p "$(dirname "$path")"
  cat > "$path.b64.tmp"
  base64 -d "$path.b64.tmp" > "$path"
  rm -f "$path.b64.tmp"
  echo "  wrote: $path ($(wc -c < "$path") bytes)"
}

