echo ""
echo "=== [2/6] Install prom-client (already pinned in package.json - this regenerates package-lock.json for THIS machine) ==="
(cd gateway && npm install prom-client@15.1.3 --save-exact)

echo ""
echo "=== [3/6] Syntax-check every changed/new JS file ==="
for f in gateway/src/config.js gateway/src/sessions.js gateway/src/index.js gateway/src/metrics.js gateway/src/logger.js gateway/src/__tests__/p06_operational_readiness.test.js; do
  node --check "$f" && echo "  OK: $f"
done

echo ""
echo "=== [4/6] hunt_gate proxy: grep for empty-catch / swallowed-rejection patterns in the changed files ==="
if grep -n "catch (err) {}" gateway/src/config.js gateway/src/sessions.js gateway/src/index.js gateway/src/metrics.js gateway/src/logger.js 2>/dev/null; then
  echo "ERROR: found an empty catch(err) {} block above - fix before proceeding." >&2
  exit 1
fi
if grep -n "catch {}" gateway/src/config.js gateway/src/sessions.js gateway/src/index.js gateway/src/metrics.js gateway/src/logger.js 2>/dev/null; then
  echo "ERROR: found an empty catch {} block above - fix before proceeding." >&2
  exit 1
fi
echo "  clean: no empty-catch patterns found"

echo ""
echo "=== [5/6] Full real-Redis test suite (all tests, via docker compose against the live redis-durable) ==="
if ! command -v docker >/dev/null 2>&1; then
  echo "ERROR: docker not found - cannot run the real-Redis test suite." >&2
  exit 1
fi
DC="docker compose"
$DC version >/dev/null 2>&1 || DC="docker-compose"

# package.json changed (prom-client added) - the gateway image's baked-in
# node_modules from any prior build is now stale. Rebuild for real (whatever
# the Dockerfile's actual COPY/RUN steps are - not assumed here) rather than
# mounting a host-built node_modules over it, which risks an
# Alpine/glibc-vs-host mismatch this script has no way to verify.
$DC build gateway

$DC run --rm \
  -e ALLOW_FAKE_WA=1 \
  -e NODE_ENV=test \
  -e LOG_LEVEL=error \
  -v "$(pwd)/gateway/src:/app/src:ro" \
  -v "$(pwd)/gateway/test-support:/app/test-support:ro" \
  gateway node --test "src/__tests__/*.test.js"

echo ""
echo "=== [6/6] Review: git status / diff --stat (NO commit performed by this script) ==="
git status --short
echo ""
git diff --stat -- gateway/src/config.js gateway/src/sessions.js gateway/src/index.js gateway/src/metrics.js gateway/src/logger.js gateway/src/__tests__/p06_operational_readiness.test.js gateway/.env.example gateway/package.json gateway/package-lock.json docs/P0_DEVIATIONS.md || true

echo ""
echo "=== Done. Nothing was committed. If the full suite above shows every test passing (the P0.6 real-process tests included), this closes out Batch A verification - let me know and I will prepare the commit script, then start on Batch B (the kill-switch)."
